from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        NEG = float('-inf')
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]
        # dp_prev[j]: max sum for first i elements using j subarrays (exactly j completed)
        dp_prev = [NEG] * (k + 1)
        dp_prev[0] = 0  # i = 0
        # dp table rows needed: dp[s] for starts s
        dp_rows = [None] * (n + 1)
        dp_rows[0] = dp_prev[:]
        # best[j] = max over valid s of dp[s][j-1] - prefix[s], for j in 1..k
        best = [NEG] * (k + 1)
        for i in range(1, n + 1):
            s = i - m
            if s >= 0:
                row = dp_rows[s]
                for j in range(1, k + 1):
                    if row[j - 1] != NEG:
                        val = row[j - 1] - prefix[s]
                        if val > best[j]:
                            best[j] = val
            cur = dp_prev[:]
            for j in range(1, k + 1):
                if best[j] != NEG:
                    cand = best[j] + prefix[i]
                    if cand > cur[j]:
                        cur[j] = cand
            dp_rows[i] = cur
            dp_prev = cur
        return int(dp_prev[k])
