class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        NEG = float('-inf')
        n = len(nums)
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
        # dp[i][j]: best using first i elements with j subarrays
        dp = [[NEG] * (k + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            dp[i][0] = 0
        end = [[NEG] * (k + 1) for _ in range(n + 1)]
        M = [NEG] * (k + 1)
        for i in range(1, n + 1):
            s = i - m
            if s >= 0:
                for j in range(1, k + 1):
                    if dp[s][j - 1] != NEG:
                        v = dp[s][j - 1] - P[s]
                        if v > M[j]:
                            M[j] = v
            for j in range(1, k + 1):
                best = M[j]
                if end[i - 1][j] > best:
                    best = end[i - 1][j]
                if best != NEG:
                    end[i][j] = P[i] + best
                dp[i][j] = max(dp[i - 1][j], end[i][j])
        return int(dp[n][k])
