    NEG = float("-inf")

    @lru_cache(maxsize=None)
    def f(pos, rem):
        # maximum sum choosing exactly rem non-overlapping subarrays,
        # each of length >= m, all lying within nums[pos:]
        if rem == 0:
            return 0
        if pos >= n:
            return NEG
        best = f(pos + 1, rem)  # element pos is not used
        # element pos starts a subarray nums[pos:e]
        s = 0
        for e in range(pos + 1, n + 1):
            s += nums[e - 1]
            if e - pos >= m:
                sub = f(e, rem - 1)
                if sub != NEG and s + sub > best:
                    best = s + sub
        return best

    res = f(0, k)
    return json.dumps(int(res))
