    a = json.loads(lines[0])
    k = json.loads(lines[1])
    m = json.loads(lines[2])
    n = len(a)

    # Exhaustive recursion: at position i with c segments still to place,
    # either leave element i unused, or start a segment [i..j] of length >= m.
    def rec(i, c):
        if c == 0:
            return 0
        if i >= n:
            return NEG
        best = rec(i + 1, c)
